16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.util.Luhn;
20	import org.springframework.samples.petclinic.util.RegistrationDatePolicy;
21	
22	import jakarta.persistence.*;
23	import jakarta.validation.constraints.NotEmpty;
24	import jakarta.validation.constraints.Pattern;
25	
26	import java.time.LocalDate;
27	import java.util.*;
28	
29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "postcode")
49	    private String postcode;
50	
51	    @Column(name = "telephone")
52	    @NotEmpty
53	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
54	    private String telephone;
55	
56	    @Column(name = "email")
57	    private String email;
58	
59	    @Column(name = "registration_date")
60	    private LocalDate registrationDate;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @Column(name = "household_id")
66	    private String householdId;
67	
68	    @Column(name = "namesake_count")
69	    private Integer namesakeCount;
70	
71	    @Column(name = "household_size")
72	    private Integer householdSize;
73	
74	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
75	    private Set<Pet> pets;
76	
77	    /**
78	     * Resolve the registration date at creation time: default it to the server's
79	     * current date when none was supplied, and roll a weekend date forward to the
80	     * next business day so every value derived from it (such as the membership
81	     * number's year segment) uses the adjusted date.
82	     */
83	    @PrePersist
84	    private void resolveRegistrationDate() {
85	        this.registrationDate = RegistrationDatePolicy.effectiveDate(this.registrationDate);
86	    }
87	
88	    public String getAddress() {
89	        return this.address;
90	    }
91	
92	    public void setAddress(String address) {
93	        this.address = address;
94	    }
95	
96	    public String getCity() {
97	        return this.city;
98	    }
99	
100	    public void setCity(String city) {
101	        this.city = city;
102	    }
103	
104	    public String getPostcode() {
105	        return this.postcode;
106	    }
107	
108	    public void setPostcode(String postcode) {
109	        this.postcode = postcode;
110	    }
111	
112	    /**
113	     * The owner's locality: the region component of its {@link #customerCode}
114	     * identity (see {@link CustomerCode}), or {@code null} when no customer code
115	     * is assigned. The region was derived from the owner's postcode and city when
116	     * the identity was minted, so the locality now follows the identity rather than
117	     * being recomputed from the current city and postcode.
118	     */
119	    public String getLocality() {
120	        return CustomerCode.regionOf(this.customerCode);
121	    }
122	
123	    public String getTelephone() {
124	        return this.telephone;
125	    }
126	
127	    public void setTelephone(String telephone) {
128	        this.telephone = telephone;
129	    }
130	
131	    public String getEmail() {
132	        return this.email;
133	    }
134	
135	    public void setEmail(String email) {
136	        this.email = email;
137	    }
138	
139	    public LocalDate getRegistrationDate() {
140	        return this.registrationDate;
141	    }
142	
143	    public void setRegistrationDate(LocalDate registrationDate) {
144	        this.registrationDate = registrationDate;
145	    }
146	
147	    public String getCustomerCode() {
148	        return this.customerCode;
149	    }
150	
151	    public void setCustomerCode(String customerCode) {
152	        this.customerCode = customerCode;
153	    }
154	
155	    /**
156	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'}
157	     * where {@code YY} is the last two digits of the {@link #registrationDate}
158	     * year (e.g. {@code "NSW-3F2A9C1D-M26"}). Derived from the owner's own fields.
159	     */
160	    public String getMembershipNumber() {
161	        if (this.customerCode == null || this.registrationDate == null) {
162	            return null;
163	        }
164	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
165	    }
166	
167	    /**
168	     * The Luhn check digit (0-9) computed over the digits of the
169	     * {@link #customerCode}, or {@code null} when no customer code is assigned.
170	     */
171	    public Integer getCheckDigit() {
172	        if (this.customerCode == null) {
173	            return null;
174	        }
175	        return Luhn.checkDigit(this.customerCode);
176	    }
177	
178	    public String getHouseholdId() {
179	        return this.householdId;
180	    }
181	
182	    public void setHouseholdId(String householdId) {
183	        this.householdId = householdId;
184	    }
185	
186	    /**
187	     * The owner's identity key: the single derived value used to detect duplicate owners. It is the
188	     * normalized telephone, the (lower-cased) email or an empty string when absent, and the
189	     * household id or an empty string when absent, joined with {@code '|'} (e.g.
190	     * {@code "+61412345678|jo@example.com|3F2A9C1D4B6E8071"}). Two owners are the same person only
191	     * when their whole identity keys are equal; because the telephone is part of the key, household
192	     * members with different telephones have different keys.
193	     */
194	    public String getIdentityKey() {
195	        return String.join("|",
196	            this.telephone == null ? "" : this.telephone,
197	            this.email == null ? "" : this.email,
198	            this.householdId == null ? "" : this.householdId);
199	    }
200	
201	    /**
202	     * The owner's membership level, a number from 1 to 3 derived from the
203	     * owner's own fields. Starts at {@code 1}, gains {@code 1} when a contact
204	     * email is on file, gains {@code 1} when the owner has no namesakes, and is
205	     * capped at {@code 3}. (Level {@code 4} is reserved for tenure.)
206	     */
207	    public Integer getMembershipLevel() {
208	        int level = 1;
209	        boolean hasEmail = this.email != null && !this.email.isEmpty();
210	        if (hasEmail) {
211	            level += 1;
212	        }
213	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
214	        if (noNamesakes) {
215	            level += 1;
216	        }
217	        return Math.min(level, 3);
218	    }
219	
220	    /**
221	     * The owner's preferred contact channel, derived from the fields on file:
222	     * {@code "EMAIL"} when a contact email is present, otherwise {@code "PHONE"}.
223	     */
224	    public String getContactPreference() {
225	        boolean hasEmail = this.email != null && !this.email.isEmpty();
226	        return hasEmail ? "EMAIL" : "PHONE";
227	    }
228	
229	    public Integer getNamesakeCount() {
230	        return this.namesakeCount;
231	    }
232	
233	    public void setNamesakeCount(Integer namesakeCount) {
234	        this.namesakeCount = namesakeCount;
235	    }
236	
237	    public Integer getHouseholdSize() {
238	        return this.householdSize;
239	    }
240	
241	    public void setHouseholdSize(Integer householdSize) {
242	        this.householdSize = householdSize;
243	    }
244	
245	    protected Set<Pet> getPetsInternal() {
246	        if (this.pets == null) {
247	            this.pets = new HashSet<>();
248	        }
249	        return this.pets;
250	    }
251	
252	    protected void setPetsInternal(Set<Pet> pets) {
253	        this.pets = pets;
254	    }
255	
256	    public List<Pet> getPets() {
257	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
258	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
259	        return Collections.unmodifiableList(sortedPets);
260	    }
261	
262	    public void setPets(List<Pet> pets) {
263	        this.pets = new HashSet<>(pets);
264	    }
265	
266	    public void addPet(Pet pet) {
267	        getPetsInternal().add(pet);
268	        pet.setOwner(this);
269	    }
270	
271	    /**
272	     * Return the Pet with the given name, or null if none found for this Owner.
273	     *
274	     * @param name to test
275	     * @return true if pet name is already in use
276	     */
277	    public Pet getPet(String name) {
278	        return getPet(name, false);
279	    }
280	
281	    /**
282	     * Return the Pet with the given name, or null if none found for this Owner.
283	     *
284	     * @param name to test
285	     * @return true if pet name is already in use
286	     */
287	    public Pet getPet(String name, boolean ignoreNew) {
288	        name = name.toLowerCase();
289	        for (Pet pet : getPetsInternal()) {
290	            if (!ignoreNew || !pet.isNew()) {
291	                String compName = pet.getName();
292	                compName = compName.toLowerCase();
293	                if (compName.equals(name)) {
294	                    return pet;
295	                }
296	            }
297	        }
298	        return null;
299	    }
300	
301	    public Pet getPet(Integer petId) {
302	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
303	    }
304	
305	    @Override
306	    public String toString() {
307	        return new ToStringCreator(this)
308	
309	            .append("id", this.getId())
310	            .append("new", this.isNew())
311	            .append("lastName", this.getLastName())
312	            .append("firstName", this.getFirstName())
313	            .append("address", this.address)
314	            .append("city", this.city)
315	            .append("telephone", this.telephone)
316	            .append("email", this.email)
317	            .toString();
318	    }
319	}
